import sys
from abc import ABC, abstractmethod

class Item(ABC):
    @abstractmethod
    def getPrice(self):
        pass

    def __del__(self):
        pass

class Product(Item):
    def __init__(self, price):
        self.price = price

    def getPrice(self):
        return self.price

class ComboPack(Item):
    def __init__(self):
        self.items = []

    def add(self, item):
        self.items.append(item)

    def getPrice(self):
        return sum(item.getPrice() for item in self.items)

    def __del__(self):
        for item in self.items:
            del item

class DiscountStrategy(ABC):
    @abstractmethod
    def applyDiscount(self, total):
        pass

class NoDiscount(DiscountStrategy):
    def applyDiscount(self, total):
        return total

class PercentageDiscount(DiscountStrategy):
    def applyDiscount(self, total):
        return total * 0.9

class FlatDiscount(DiscountStrategy):
    def applyDiscount(self, total):
        return total - 5000

def create_sample_combo():
    combo = ComboPack()
    combo.add(Product(10000))
    combo.add(Product(20000))
    combo.add(Product(15000))
    combo.add(Product(11000))
    return combo

def main():
    lines = sys.stdin.read().strip().split('\n')
    if len(lines) >= 2:
        item_type = lines[0].strip()
        discount_type = lines[1].strip()
    elif len(lines) == 1:
        item_type = lines[0].strip()
        discount_type = "None"
    else:
        return

    combo = create_sample_combo()
    total_price = combo.getPrice()

    if discount_type == "Percentage":
        discount_strategy = PercentageDiscount()
    elif discount_type == "Flat":
        discount_strategy = FlatDiscount()
    else:
        discount_strategy = NoDiscount()

    final_price = discount_strategy.applyDiscount(total_price)

    print(f"Total Price before discount: {total_price}")
    print(f"Final Price after discount: {int(final_price)}")

if __name__ == "__main__":
    main()
